Check the special cases first, because typeof reports them all as object and hides the difference. Only then fall back to typeof.

code:
function describeType(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  if (value instanceof Date) return 'date';
  return typeof value;
}
const samples = [1, 'a', null, [1], new Date(0), { a: 1 }];
console.log(samples.map(describeType).join(', ')); // number, string, null, array, date, object

output:
number, string, null, array, date, object

Null counts as a primitive even though its typeof says object, so test for null separately before ruling out object and function.

code:
function isPrimitive(value) {
  return value === null || (typeof value !== 'object' && typeof value !== 'function');
}
const samples = [1, 'a', true, null, undefined, {}, () => 1];
console.log(samples.map(isPrimitive).join(', ')); // true, true, true, true, true, false, false

output:
true, true, true, true, true, false, false

typeof says function for all three, so only the prototype property tells an arrow function apart from a normal function.

code:
function named() {}
const arrow = () => {};
class Suite {}
console.log(typeof named, typeof arrow, typeof Suite); // function function function
console.log(Boolean(named.prototype), Boolean(arrow.prototype), Boolean(Suite.prototype)); // true false true

output:
function function function
true false true

All three are objects to typeof, so an instanceof check is the honest way to prove what a value actually is.

code:
const pattern = /abc/;
const store = new Map([['a', 1]]);
const unique = new Set([1, 2]);
console.log(typeof pattern, typeof store, typeof unique); // object object object
console.log(pattern instanceof RegExp, store instanceof Map, unique instanceof Set); // true true true

output:
object object object
true true true

One pass with a running object keyed by the typeof string is enough, and JSON.stringify gives you a stable order for the log line.

code:
const values = [1, 'a', true, 2, 'b'];
const counts = {};
for (const value of values) {
  const type = typeof value;
  counts[type] = (counts[type] || 0) + 1;
}
console.log(JSON.stringify(counts)); // {"number":2,"string":2,"boolean":1}

output:
{"number":2,"string":2,"boolean":1}

Walk both arrays together and compare tags, stopping at the first place they differ. Stopping early is what makes this cheap on long payloads.

code:
function firstTypeMismatch(a, b) {
  const limit = Math.min(a.length, b.length);
  for (let i = 0; i < limit; i++) {
    if (typeof a[i] !== typeof b[i]) return i;
  }
  return -1;
}
console.log(firstTypeMismatch([1, 2, 3], [1, '2', 3])); // 1
console.log(firstTypeMismatch([1], [1, 'x'])); // -1

output:
1
-1

Turning each value into text with String keeps null readable instead of crashing the way a plain string join would not.

code:
function describeList(values) {
  return values.map((value) => String(value) + ':' + typeof value);
}
console.log(describeList([1, '1', null]).join(' ')); // 1:number 1:string null:object

output:
1:number 1:string null:object

Collect the tags in a Set so each one is counted once, then copy the Set into an array so it can be sorted without changing the Set.

code:
function typeSummary(values) {
  const tags = new Set(values.map((value) => typeof value));
  return values.length + ' values, ' + tags.size + ' types: ' + [...tags].sort().join(',');
}
console.log(typeSummary([1, 'a', 2, true])); // 4 values, 3 types: boolean,number,string

output:
4 values, 3 types: boolean,number,string

Create the bucket on first sight with a logical assignment, then push into it. That avoids a hasOwnProperty check on every value.

code:
function groupByType(values) {
  const groups = {};
  for (const value of values) {
    (groups[typeof value] ||= []).push(String(value));
  }
  return groups;
}
console.log(JSON.stringify(groupByType([1, 'a', 2]))); // {"number":["1","2"],"string":["a"]}

output:
{"number":["1","2"],"string":["a"]}

Check the tag first so strings are never converted, then check the value so NaN and Infinity are rejected too.

code:
function isFiniteNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}
const samples = [1, 1.5, NaN, Infinity, '2'];
console.log(samples.map(isFiniteNumber).join(', ')); // true, true, false, false, false

output:
true, true, false, false, false

Branch on the typeof tag first, and only treat a value as a number once you know the tag really is number.

code:
function describeSize(value) {
  if (typeof value === 'bigint') return 'bigint:' + value.toString();
  return typeof value + ':' + Number.isInteger(value);
}
console.log(describeSize(10n)); // bigint:10
console.log(describeSize(10)); // number:true

output:
bigint:10
number:true

Object.entries gives you the key and the value together, so one map produces the whole report line.

code:
function typeMap(obj) {
  return Object.entries(obj).map(([key, value]) => key + ':' + typeof value).join(', ');
}
const response = { id: 7, name: 'cart', items: [], paid: false, note: null };
console.log(typeMap(response)); // id:number, name:string, items:object, paid:boolean, note:object

output:
id:number, name:string, items:object, paid:boolean, note:object

A missing field is undefined rather than a crash, but reading a field of undefined is a TypeError. That is why optional chaining exists.

code:
const response = { data: { id: 1 } };
console.log(typeof response.data.items); // undefined
console.log(typeof response.error); // undefined
try {
  console.log(typeof response.error.code);
} catch (err) {
  console.log(err.constructor.name); // TypeError
}

output:
undefined
undefined
TypeError

The string 'undefined' and the real undefined are different values with the same typeof. Comparing against undefined first tells them apart.

code:
function display(value) {
  if (value === undefined) return 'MISSING';
  if (value === null) return 'NULL';
  return typeof value + ':' + String(value);
}
console.log([undefined, null, 'undefined', 0].map(display).join(' | ')); // MISSING | NULL | string:undefined | number:0

output:
MISSING | NULL | string:undefined | number:0

Handle each type on its own terms instead of relying on a single truthiness test, because 0 is a real value that happens to look falsy.

code:
function isEmptyValue(value) {
  if (value === null || value === undefined) return true;
  if (typeof value === 'string') return value.trim() === '';
  if (Array.isArray(value)) return value.length === 0;
  return false;
}
console.log(['', ' ', 0, [], null, 'x'].map(isEmptyValue).join(', ')); // true, true, false, true, true, false

output:
true, true, false, true, true, false

typeof object alone is not enough because null shares the tag, so add a null check before you count.

code:
function countObjects(values) {
  return values.filter((value) => typeof value === 'object' && value !== null).length;
}
console.log(countObjects([{}, [], null, 'x', 5])); // 2

output:
2

Put the tags into a Set: one entry means the array is uniform, more than one means it is mixed.

code:
function typeOfItems(list) {
  const tags = new Set(list.map((item) => typeof item));
  return tags.size === 1 ? [...tags][0] : 'mixed';
}
console.log(typeOfItems([1, 2, 3])); // number
console.log(typeOfItems([1, '2'])); // mixed

output:
number
mixed

Look at the array case first, then reuse the same function on the first item so nested shapes describe themselves.

code:
function describeDeep(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array of ' + describeDeep(value[0]);
  if (value instanceof Date) return 'date';
  return typeof value;
}
console.log(describeDeep([1, 2]), describeDeep(new Date(0))); // array of number date
console.log(describeDeep(null), describeDeep({ a: 1 })); // null object

output:
array of number date
null object

Use every to check the shape of the contents, then report the length so the log line tells you how much data came back.

code:
function describeCollection(value) {
  if (!Array.isArray(value)) return typeof value;
  const shape = value.every((item) => Array.isArray(item)) ? 'array of arrays' : 'flat array';
  return shape + ' of length ' + value.length;
}
console.log(describeCollection([[1], [2]])); // array of arrays of length 2
console.log(describeCollection([1, 2])); // flat array of length 2

output:
array of arrays of length 2
flat array of length 2

Recurse into arrays element by element and compare tags at every level, so a nested shape mismatch is caught too.

code:
function sameDeepType(a, b) {
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  if (Array.isArray(a)) {
    return a.length === b.length && a.every((item, i) => sameDeepType(item, b[i]));
  }
  return typeof a === typeof b;
}
console.log(sameDeepType([1, 2], [1, 2]), sameDeepType([1], ['1'])); // true false

output:
true false

typeof on the primitive string is string and on the boxed version it is object, so the check also catches wrongly wrapped data.

code:
function isText(value) {
  return typeof value === 'string';
}
const samples = ['a', new String('a'), 1, ['a']];
console.log(samples.map(isText).join(', ')); // true, false, false, false

output:
true, false, false, false

An instance is an object even though the class is a function, and instanceof is the check that links the two back together.

code:
class Checkout {
  constructor() {
    this.total = 0;
  }
}
const page = new Checkout();
console.log(typeof page, typeof Checkout); // object function
console.log(page instanceof Checkout, page.constructor === Checkout); // true true

output:
object function
true true

Decide the group from the tag itself, which puts null in the object group because typeof calls null an object. That surprise is the reason to test for null separately.

code:
function groupCount(values) {
  const groups = { primitive: 0, object: 0 };
  for (const value of values) {
    const tag = typeof value;
    groups[tag === 'object' || tag === 'function' ? 'object' : 'primitive'] += 1;
  }
  return groups;
}
console.log(JSON.stringify(groupCount([1, 'a', {}, null, () => 1]))); // {"primitive":2,"object":3}

output:
{"primitive":2,"object":3}

Start from the tag so strings are rejected, then use Number.isNaN and Number.isInteger to split the numbers into two groups.

code:
function typeOfNumber(value) {
  if (typeof value !== 'number') return 'not-a-number';
  if (Number.isNaN(value)) return 'not-a-number';
  return Number.isInteger(value) ? 'integer' : 'decimal';
}
console.log([7, 7.5, 'abc'].map(typeOfNumber).join(', ')); // integer, decimal, not-a-number

output:
integer, decimal, not-a-number

Return early when the tag is not function, then use the missing prototype property as the tell between a normal function and an arrow function.

code:
function describeFn(fn) {
  if (typeof fn !== 'function') return 'not a function';
  return fn.prototype ? 'has prototype' : 'arrow or method';
}
console.log(describeFn(function () {}), describeFn(() => {})); // has prototype arrow or method
console.log(describeFn('x')); // not a function

output:
has prototype arrow or method
not a function

Compare the tags directly. The last pair is the reminder that typeof hides the difference between null and a real object.

code:
function sameType(a, b) {
  return typeof a === typeof b;
}
const pairs = [[1, 2], [1, '2'], [null, {}]];
console.log(pairs.map(([a, b]) => sameType(a, b)).join(', ')); // true, false, true

output:
true, false, true
